  if(part.lang==='ko'){const timing=generatedVoices.get(key)?.timing;recordVoice({...timing});SC.stopSpeech();SC.toast(`韩语朗读失败：${timing?.error||'未收到有效语音。'} 点击内容可重试，文字仍可学习。`);return;}
