function moreButton(kind,scope){return `<button type="button" class="nav-item sidebar-more" data-more-kind="${kind}" data-more-scope="${SC.esc(scope||'')}" aria-label="更多${({group:'项目',project:'笔记本',book:'卡片',children:'内容'})[kind]}" title="更多">${SC.icon('more')}<span>更多</span></button>`;}
function limited(list,render,kind,scope=''){return visibleContainers(list,kind,scope).map(render).join('')+(list.length>3?moreButton(kind,scope):'');}
function groupChildren(groupId){return [...allContainers(notebooksInScope(groupId),'project',groupId),...directBooks(groupId)];}
