function bookNav(book){return `<div class="book-nav" draggable="${!book.special}" data-book="${SC.esc(book.id)}">${navButton(book.special?'words':cardRoute(book.kind),book.name,book.special?'reviewRepeat':SC.cardIcon(book.kind),book.id,book.special?'':'child')}</div>`;}
