  SC.$('#sidebarNav').querySelectorAll('[data-project]').forEach(element=>{element.ondragstart=event=>{if(event.target.closest('[data-book]'))return;SC.stopSpeech();SC.sidebarDragging=true;event.dataTransfer.setData('text/scrawl-notebook',element.dataset.project);SC.$('#hoverPreview').hidden=true;};element.oncontextmenu=event=>{event.preventDefault();event.stopPropagation();projectMenu(element.dataset.project,event.clientX,event.clientY);};element.ondragover=event=>{if(event.dataTransfer.types.includes('text/scrawl-book')){event.preventDefault();element.classList.add('drag-over');}};element.ondragleave=()=>element.classList.remove('drag-over');element.ondrop=event=>{const bookId=event.dataTransfer.getData('text/scrawl-book');if(!bookId)return;event.preventDefault();event.stopPropagation();element.classList.remove('drag-over');moveBook(bookId,element.dataset.project);};});
