  SC.$('#otherBooks').ondragover=event=>event.preventDefault();SC.$('#otherBooks').ondrop=event=>{event.preventDefault();const notebookId=event.dataTransfer.getData('text/scrawl-notebook');if(notebookId)moveNotebook(notebookId,null);else moveBook(event.dataTransfer.getData('text/scrawl-book'),null);};
