  for(const line of evidence.split('\n')){const text=line.trim().replace(/^\d+[、.)]\s*/,'');const pair=raw&&text.match(/^([가-힣][^A-Za-z.!?。！？]*[.!?。！？])\s+([A-Z][^가-힣\u4e00-\u9fff]*[.!?])$/);if(pair)originals.set(pair[1],pair[2]);else if(sentence(text))originals.set(text,'');}
